import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "./DetailsProduct.scss";

const DetailsProduct = () => {
  const { productId } = useParams();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedSize, setSelectedSize] = useState(null);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const response = await fetch("/products.json");

        if (!response.ok) {
          throw new Error("Erro ao carregar os produtos");
        }

        const data = await response.json();
        const selectedProduct = data.find((p) => String(p.productId) === String(productId));

        console.log("Produto selecionado:", selectedProduct);
        setProduct(selectedProduct);
      } catch (error) {
        console.error("Erro ao carregar o produto:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchProduct();
  }, [productId]);

  if (loading) return <p>Carregando...</p>;
  if (!product) return <p>Produto não encontrado.</p>;

  const priceData = product.items?.[0]?.sellers?.[0]?.commertialOffer;
  const priceVista = priceData?.Price?.toFixed(2);
  const priceParcelado = priceData?.Installments?.[0];

  const handleSizeSelection = (size) => {
    setSelectedSize(size);
  };

  return (
    <div className="details-product">
      {/* Galeria de Imagens */}
      <div className="product-gallery">
        {product.items?.[0]?.images?.map((img, index) => (
          <img key={index} src={img.imageUrl} alt={product.productName} />
        ))}
      </div>

      {/* Informações do Produto */}
      <div className="product-info">
        <h1>{product.productName}</h1>

        {/* Preço */}
        <div className="price">
          <p className="vista">R$ {priceVista} à vista</p>
          {priceParcelado && (
            <p className="parcelado">
              ou {priceParcelado.NumberOfInstallments}x de R$ {priceParcelado.Value.toFixed(2)}
            </p>
          )}
        </div>

        {/* Seleção de Tamanho */}
        <div className="size-selection">
          <span>Selecione um tamanho:</span>
          <div className="size-buttons">
            {["PP", "P", "M", "G", "GG"].map((size) => (
              <button
                key={size}
                className={selectedSize === size ? "selected" : ""}
                onClick={() => handleSizeSelection(size)}
              >
                {size}
              </button>
            ))}
          </div>
        </div>

        {/* Descrição do Produto */}
        <div className="product-description">
          <p>{product.description || product.metaTagDescription || "Sem descrição disponível."}</p>
        </div>

        {/* Botão de Compra */}
        <button className="add-to-cart">ADICIONAR À SACOLA</button>
      </div>
    </div>
  );
};

export default DetailsProduct;
